const traverseEL = (f, x2) => {
  switch (x2.$) {
    case "Nil": {
      return (st) => ({ $: "MkPair", a: [{ $: "Right", a: [{ $: "Nil", a: [] }] }, st] });
    }
    case "Cons": {
      const x = x2.a[0];
      const xs = x2.a[1];
      const m = f(x);
      return (st) => {
        const x1 = m(st);
        switch (x1.$) {
          case "MkPair": {
            const x11 = x1.a[0];
            const st1 = x1.a[1];
            switch (x11.$) {
              case "Left": {
                const e = x11.a[0];
                return { $: "MkPair", a: [{ $: "Left", a: [e] }, st1] };
              }
              case "Right": {
                const x3 = x11.a[0];
                const m1 = traverseEL(f, xs);
                const x12 = m1(st1);
                switch (x12.$) {
                  case "MkPair": {
                    const x111 = x12.a[0];
                    const st2 = x12.a[1];
                    switch (x111.$) {
                      case "Left": {
                        const e = x111.a[0];
                        return { $: "MkPair", a: [{ $: "Left", a: [e] }, st2] };
                      }
                      case "Right": {
                        const x4 = x111.a[0];
                        return { $: "MkPair", a: [{ $: "Right", a: [{ $: "Cons", a: [x3, x4] }] }, st2] };
                      }
                    }
                    return $nomatch(x111);
                  }
                }
                return $nomatch(x12);
              }
            }
            return $nomatch(x11);
          }
        }
        return $nomatch(x1);
      };
    }
  }
  return $nomatch(x2);
};

