const explicitNames = (x1$) => {
  let $root, $hole = null, $at = 0;
  for (;;) {
    const x1 = x1$;
    switch (x1.$) {
      case "Nil": {
        const r = { $: "Nil", a: [] };
        if ($hole) { $hole.a[$at] = r; return $root; }
        return r;
      }
      case "Cons": {
        const ab = x1.a[0];
        const rest = x1.a[1];
        const x11 = (() => {
          const s = ab.implicit;
          switch (s.$) {
            case "Expl": {
              return { $: "True", a: [] };
            }
            case "Impl": {
              return { $: "False", a: [] };
            }
            case "Inst": {
              return { $: "False", a: [] };
            }
          }
          return $nomatch(s);
        })();
        const s = (() => {
          switch (x11.$) {
            case "True": {
              return { $: "False", a: [] };
            }
            case "False": {
              return { $: "True", a: [] };
            }
          }
          return $nomatch(x11);
        })();
        switch (s.$) {
          case "True": {
            x1$ = rest; continue;
          }
          case "False": {
            const cell = { $: "Cons", a: [ab.name, undefined] };
            if ($hole) $hole.a[$at] = cell; else $root = cell;
            $hole = cell; $at = 1;
            x1$ = rest; continue;
          }
        }
        return $nomatch(s);
      }
    }
    return $nomatch(x1);
  }
};

